import { chromium } from 'playwright'; import fs from 'fs';
const BASE='https://www.statesideqm.com',THEME='158900125851',ROOT='/collections/state-guard-series',OUT='sep18-full-current-audit-discovery';fs.mkdirSync(OUT,{recursive:true});
const b=await chromium.launch({headless:true});const c=await b.newContext({viewport:{width:1440,height:1000}});const p=await c.newPage();p.setDefaultNavigationTimeout(70000);
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function establish(){await p.goto(BASE+'/?preview_theme_id='+THEME,{waitUntil:'domcontentloaded',timeout:70000});await p.waitForLoadState('load',{timeout:15000}).catch(()=>{});await sleep(1200);const t=await p.evaluate(()=>({id:String(window.Shopify?.theme?.id||''),name:String(window.Shopify?.theme?.name||'')}));if(t.id!==THEME)throw new Error('wrong preview '+JSON.stringify(t));return t}
async function discover(route){await p.goto(BASE+route,{waitUntil:'domcontentloaded',timeout:70000});await p.waitForLoadState('load',{timeout:15000}).catch(()=>{});await sleep(900);return p.evaluate(({base})=>{const main=document.getElementById('MainContent')||document.body,vis=e=>{const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&!e.hidden&&r.width>8&&r.height>20},out=[];for(const a of main.querySelectorAll('a[href]')){if(!vis(a))continue;let u;try{u=new URL(a.href,base)}catch{continue}if(u.origin!==new URL(base).origin||!/^\/(collections|pages)\//.test(u.pathname)||/\/products\//.test(u.pathname))continue;u.searchParams.delete('preview_theme_id');u.hash='';const label=(a.getAttribute('aria-label')||a.textContent||a.querySelector('img')?.alt||'').replace(/\s+/g,' ').trim();if(!label)continue;const r=a.getBoundingClientRect(),card=!!(a.querySelector('img,svg')||a.closest('[class*="card"],[class*="grid"],[data-sq-state-guard-root]')||r.width>140||r.height>50);if(!card)continue;out.push({label:label.slice(0,220),route:u.pathname+u.search})}const seen=new Set();return out.filter(x=>!seen.has(x.route)&&(seen.add(x.route),true))},{base:BASE})}
const theme=await establish();const home=await discover('/');await sleep(3000);const sg=await discover(ROOT);
const all=[...home.map(x=>({...x,group:'homepage',source:'/'})),...sg.map(x=>({...x,group:'state-guard-root',source:ROOT}))];
const chunks=[];for(let i=0;i<all.length;i+=3)chunks.push({shard:String(chunks.length+1).padStart(2,'0'),routesB64:Buffer.from(JSON.stringify(all.slice(i,i+3))).toString('base64')});
const matrix={include:chunks};fs.writeFileSync(OUT+'/coverage.json',JSON.stringify({generatedAt:new Date().toISOString(),theme,homeCount:home.length,stateGuardRootCount:sg.length,total:all.length,home,sg,matrix},null,2));
fs.appendFileSync(process.env.GITHUB_OUTPUT,'matrix='+JSON.stringify(matrix)+'\n');fs.appendFileSync(process.env.GITHUB_OUTPUT,'home_count='+home.length+'\n');fs.appendFileSync(process.env.GITHUB_OUTPUT,'sg_count='+sg.length+'\n');fs.appendFileSync(process.env.GITHUB_OUTPUT,'total='+all.length+'\n');
console.log('DISCOVERY',JSON.stringify({theme,homeCount:home.length,stateGuardRootCount:sg.length,total:all.length,shards:chunks.length}));await c.close();await b.close();